intro(s,4,'Le riz — «рис». В просьбе без точной меры: Je voudrais du riz. — «Мне бы хотелось риса». Сравните уже показанные des tomates и des pâtes. Для риса в нашем образце сохраняется du; для двух других выбранных продуктов — показанная форма des. Общая таблица всех исключений не нужна.',['riz'],[('Le riz','лё ри́'),('Je voudrais du riz.','жё вудрэ дю ри́'),('des tomates','дэ тома́т'),('des pâtes','дэ па́т'),('du','дю'),('des','дэ')],('Je voudrais du riz. Je voudrais des pâtes.','жё вудрэ дю ри́. жё вудрэ дэ па́т.'))
choose(s,'vocabulary',[U],['je-voudrais','riz','pates','tomate'],['riz'],'Нужно попросить риса без точной меры. Что выбрать?',ru('Выберите продукт из условия.'),[fr('Je voudrais des pâtes.','жё вудрэ дэ па́т.'),fr('Je voudrais du riz.','жё вудрэ дю ри́.'),fr('Je voudrais des tomates.','жё вудрэ дэ тома́т.')],1,'Выбран рис.','Нужен рис; макароны и помидоры меняют продукт.')
