page(s,[('Продукты списка',['В список могут входить несколько разных продуктов. Сохраняйте каждое название, не подменяя рис макаронами.'],[ex('La liste : des tomates, des pâtes, du riz.','Список: помидоры, макароны, рис.','ла лист: дэ томат, дэ пат, дю ри́')]),('Список и отдельная просьба',['Отдельная просьба может назвать только часть списка. Вопрос о ней решается по самой просьбе, а не по всему перечню.'],[ex('Je voudrais du riz et du lait.','Мне бы хотелось риса и молока.','жё вудрэ дю ри э дю лэ́')]),('Показанные сочетания',['Выбранные формы продуктов повторяются целиком. Новых исключений частичного артикля здесь не вводится.'],[W['riz']['example'],W['pates']['example']])])

