page(s,[('Мера и упаковка',['Килограмм задаёт массу. Пачка, бутылка и лоток называют упаковку; её массу нельзя выводить без отдельной информации.'],[W['kilo']['example'],W['barquette']['example']]),('Содержимое после упаковки',['В показанных сочетаниях сохраняется известная связка между упаковкой и содержимым. Перед водой повторяется форма с апострофом.'],[W['bouteille']['example'],ex('Une bouteille d’eau.','Бутылка воды.','юн бутэй до́')]),('Количество одинаковых упаковок',['Известное число относится к упаковкам названного продукта. Не переносите число на соседнюю позицию списка.'],[ex('Deux bouteilles de lait.','Две бутылки молока.','дё бутэй дё лэ́')])])
